import com.sun.tools.javac.tree.JCTree.JCMethodInvocation;
import com.sun.tools.javac.tree.JCTree.JCStatement;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;
import com.sun.tools.javac.tree.JCTree.JCCompilationUnit;
import com.sun.tools.javac.tree.JCTree.JCImport;
import com.sun.tools.javac.util.List;
import com.sun.tools.javac.util.ListBuffer;
import com.sun.tools.javac.util.Name;

import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.configuration.FlagUsageType;
import lombok.experimental.Helper;
import lombok.javac.Javac;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacAugments;
import lombok.javac.JavacNode;
import lombok.javac.JavacTreeMaker;
import lombok.spi.Provides;

@Provides
public class HandleHelper extends JavacAnnotationHandler<Helper> {
	private List<JCStatement> getStatementsFromJcNode(JCTree tree) {
		if (tree instanceof JCBlock) return ((JCBlock) tree).stats;
		if (tree instanceof JCCase) return ((JCCase) tree).stats;
		return null;
	}

	private void setStatementsOfJcNode(JCTree tree, List<JCStatement> statements) {
		if (tree instanceof JCBlock) ((JCBlock) tree).stats = statements;
		else if (tree instanceof JCCase) ((JCCase) tree).stats = statements;
		else throw new IllegalArgumentException("Can't set statements on node type: " + tree.getClass());
	}

	@Override public void handle(AnnotationValues<Helper> annotation, JCAnnotation ast, final JavacNode annotationNode) {
		FlagUsageType helperFlagUsage = annotationNode.getAst().readConfiguration(ConfigurationKeys.HELPER_FLAG_USAGE);
		FlagUsageType experimentalFlagUsage = annotationNode.getAst().readConfiguration(ConfigurationKeys.EXPERIMENTAL_FLAG_USAGE);
		FlagUsageType flaggedUsage = null;
		String flaggedFeatureName = null;
		if (helperFlagUsage == FlagUsageType.ERROR) {
			flaggedUsage = helperFlagUsage;
			flaggedFeatureName = "@Helper";
		} else if (experimentalFlagUsage == FlagUsageType.ERROR) {
			flaggedUsage = experimentalFlagUsage;
			flaggedFeatureName = "any lombok.experimental feature";
		} else if (helperFlagUsage == FlagUsageType.WARNING) {
			flaggedUsage = helperFlagUsage;
			flaggedFeatureName = "@Helper";
		} else {
			flaggedUsage = experimentalFlagUsage;
			flaggedFeatureName = "any lombok.experimental feature";
		}
		if (flaggedUsage != null) {
			String flaggedMessage = "Use of " + flaggedFeatureName + " is flagged according to lombok configuration.";
			if (flaggedUsage == FlagUsageType.WARNING) {
				annotationNode.addWarning(flaggedMessage);
			} else if (flaggedUsage == FlagUsageType.ERROR) {
				annotationNode.addError(flaggedMessage);
			}
		}

		boolean canDeleteHelperAnnotation = !inNetbeansEditor(annotationNode) && annotationNode.shouldDeleteLombokAnnotations();
		if (canDeleteHelperAnnotation) {
			JavacNode annotationParent = annotationNode.directUp();
			if (annotationParent != null && annotationParent.getKind() == Kind.TYPE) {
				try {
					JCClassDecl annotatedOwnerType = (JCClassDecl) annotationParent.get();
					ListBuffer<JCAnnotation> remainingTypeAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : annotatedOwnerType.mods.annotations) {
						if (existingAnnotation != annotationNode.get()) {
							remainingTypeAnnotations.append(existingAnnotation);
						}
					}
					annotatedOwnerType.mods.annotations = remainingTypeAnnotations.toList();
				} catch (ClassCastException unusualAnnotationTarget) {
					// something rather odd has been annotated. Better to just break only delombok instead of everything.
				}
				annotationParent.getAst().setChanged();
				JCCompilationUnit compilationUnit = (JCCompilationUnit) annotationNode.top().get();
				String helperAnnotationName = Helper.class.getName();
				for (JCTree compilationUnitDef : compilationUnit.defs) {
					if (compilationUnitDef instanceof JCImport) {
						JCImport importDecl = (JCImport) compilationUnitDef;
						if (!importDecl.staticImport) {
							if (Javac.getQualid(importDecl).toString().equals(helperAnnotationName)) {
								JavacAugments.JCImport_deletable.set(importDecl, true);
							}
						}
					}
				}
			} else {
				deleteAnnotationIfNeccessary(annotationNode, Helper.class);
			}
		}

		JavacNode annotatedType = annotationNode.up();
		JavacNode containingBlock = annotatedType == null ? null : annotatedType.directUp();
		List<JCStatement> origStatements = getStatementsFromJcNode(containingBlock == null ? null : containingBlock.get());

		if (annotatedType != null) {
			if (annotatedType.getKind() == Kind.TYPE) {
				if (origStatements != null) {
					JCClassDecl annotatedType_ = (JCClassDecl) annotatedType.get();
					Iterator<JCStatement> it = origStatements.iterator();
					while (it.hasNext()) {
						JCStatement candidateStatement = it.next();
						if (candidateStatement == annotatedType_) {
							break;
						}
					}

					java.util.List<String> knownMethodNames = new ArrayList<String>();
					for (JavacNode ch : annotatedType.down()) {
						if (ch.getKind() == Kind.METHOD) {
							String n = ch.getName();
							if (n != null && !n.isEmpty() && n.charAt(0) != '<') {
								knownMethodNames.add(n);
							}
						}
					}

					Collections.sort(knownMethodNames);
					final String[] knownMethodNames_ = knownMethodNames.toArray(new String[0]);

					final Name helperName = annotationNode.toName("$" + annotatedType_.name);
					final boolean[] helperUsed = new boolean[1];
					final JavacTreeMaker maker = annotationNode.getTreeMaker();

					TreeVisitor<Void, Void> visitor = new TreeScanner<Void, Void>() {
						@Override public Void visitMethodInvocation(MethodInvocationTree node, Void p) {
							JCMethodInvocation jcmi = (JCMethodInvocation) node;
							apply(jcmi);
							return super.visitMethodInvocation(node, p);
						}

						private void apply(JCMethodInvocation jcmi) {
							if (!(jcmi.meth instanceof JCIdent)) return;
							JCIdent jci = (JCIdent) jcmi.meth;
							if (Arrays.binarySearch(knownMethodNames_, jci.name.toString()) < 0) return;
							jcmi.meth = maker.Select(maker.Ident(helperName), jci.name);
							recursiveSetGeneratedBy(jcmi.meth, annotationNode);
							helperUsed[0] = true;
						}
					};

					while (it.hasNext()) {
						JCStatement stat = it.next();
						stat.accept(visitor, null);
					}

					if (!helperUsed[0]) {
						annotationNode.addWarning("No methods of this helper class are ever used.");
						return;
					}

					ListBuffer<JCStatement> newStatements = new ListBuffer<JCStatement>();
					boolean mark = false;
					for (JCStatement stat : origStatements) {
						newStatements.append(stat);
						if (!mark) {
							if (stat == annotatedType_) {
								mark = true;
								Name helperTypeName = annotatedType_.name;
								List<JCExpression> noTypeArguments = List.<JCExpression>nil();
								List<JCExpression> noConstructorArguments = List.<JCExpression>nil();
								JCExpression helperTypeExpression = maker.Ident(helperTypeName);
								JCExpression helperAllocation = maker.NewClass(null, noTypeArguments, helperTypeExpression, noConstructorArguments, null);
								JCExpression helperVariableType = maker.Ident(helperTypeName);
								JCVariableDecl helperDeclaration = maker.VarDef(maker.Modifiers(Flags.FINAL), helperName, helperVariableType, helperAllocation);
								recursiveSetGeneratedBy(helperDeclaration, annotationNode);
								newStatements.append(helperDeclaration);
							}
						}
					}
					setStatementsOfJcNode(containingBlock.get(), newStatements.toList());
				} else {
					annotationNode.addError("@Helper is legal only on method-local classes.");
					return;
				}
			} else {
				annotationNode.addError("@Helper is legal only on method-local classes.");
				return;
			}
		} else {
			annotationNode.addError("@Helper is legal only on method-local classes.");
			return;
		}
	}
}

