	addIfNotNull(childNodes, buildTree(getVarOrRecordPattern(loop), Kind.STATEMENT));
	addIfNotNull(childNodes, buildTree(loop.expr, Kind.STATEMENT));
	addIfNotNull(childNodes, buildStatement(loop.body));

